	prevEMA2 = math.FMA(sp.emaBeta, prevEMA2, float64(sp.optInK_1*prevEMA1))
	prevEMA3 = math.FMA(sp.emaBeta, prevEMA3, float64(sp.optInK_1*prevEMA2))
	cur_outReal = prevEMA3 + (float64(3.0*prevEMA1) - float64(3.0*prevEMA2))
	return cur_outReal, nil
