func (c *Core) temaOpenAndFillInternal(inReal []float64, startIdx, optInTimePeriod int32, outBegIdx, outNBElement *int32, outReal []float64) (*TEMAStream, error) {
	sp := &TEMAStream{core: c}
	if retCode := c.temaOpenImpl(sp, inReal, startIdx, optInTimePeriod, outBegIdx, outNBElement, outReal, 1); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func (c *Core) temaOpenInternal(inReal []float64, startIdx, optInTimePeriod int32) (*TEMAStream, error) {
	sp := &TEMAStream{core: c}
	var outBegIdx, outNBElement int32
	var sink_outReal [1]float64
	if retCode := c.temaOpenImpl(sp, inReal, startIdx, optInTimePeriod, &outBegIdx, &outNBElement, sink_outReal[:], 0); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, nil
}

// TEMAOpen opens a live [TEMAStream] on a warm-up history, oldest bar first,
// and returns it with its value at the last history bar, the value [Core.TEMA]
// writes there.
//
// inReal is the history; the parameters are those of [Core.TEMA].
//
// The error is [InsufficientHistory] for a history of at most
// [Core.TEMALookback] bars, [OutOfRangeEndIndex] for one longer than
// [IndexMax]+1 bars, and [BadParam] for a parameter out of range.
func (c *Core) TEMAOpen(inReal []float64, optInTimePeriod int) (*TEMAStream, float64, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, 0, BadParam
	}
	sp, err := c.temaOpenInternal(inReal, 0, int32(optInTimePeriod))
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outReal, nil
}

// TEMAOpenAndFill opens a stream as [Core.TEMAOpen] does and also writes the
// outputs over the whole history, as [Core.TEMA] writes them for bars 0 through
// len(inReal)-1, returning that range.
//
// Each output must hold len(inReal) minus [Core.TEMALookback] values and share
// no memory with an input or another output.
//
// The errors are those of [Core.TEMAOpen], and [BadParam] for an output that is
// empty, too short or sharing memory. A slice whose capacity a three-index
// expression cut, as slices.Clip does, can escape the sharing check.
func (c *Core) TEMAOpenAndFill(inReal []float64, optInTimePeriod int, outReal []float64) (*TEMAStream, OutRange, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inReal) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.temaLookback(int32(optInTimePeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inReal)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && overlaps(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.temaOpenAndFillInternal(inReal, 0, int32(optInTimePeriod), &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}

func temaStepTape(sp *TEMAStream, tape []float64, tapeBase, tapeMask int32, inReal float64) float64 {
	temaStepImpl(sp, inReal)
	sp.outRangeCount++
	return sp.cur_outReal
}

func temaPeekTape(sp *TEMAStream, tape []float64, tapeBase, tapeMask int32, inReal float64) (float64, error) {
	return sp.Peek(inReal)
}

func temaTapeDetach(sp *TEMAStream) int32 {
	return 0
}
